newLore{
	id = "shertul-fortress-8",
	category = "sher'tul",
	name = _t"eighth mural painting", always_pop = true,
	image = "shertul_fortress_lore8.png",
	lore = function() return _t[[The large mural shows the great god spread on the ground, with the dark staff held against his chest. Sher'Tul surround him, some hacking off his limbs, cutting out his tongue, and binding him with chains. A burst of light flares up from where a tall Sher'Tul warrior is gouging his eye with a black-bladed halberd. In the background a Sher'Tul mage beckons to a huge chasm in the ground.
The text beneath says simply ]]..(not game.player:attr("speaks_shertul") and _t[[#{italic}#'Meas Abar.'#{normal}#]] or _t[[#{italic}#'The Great Sin.'#{normal}#]])
	end,
}

